from __future__ import annotations

from collections.abc import Sequence
from dataclasses import replace

import sympy as sp

from ..exact_arithmetic import exact_sign
from ..structural_keys import symbol_identity_key
from .cache import (
    CACHE,
    expr_key,
    mark_refinement_decisive,
    record_sign_refinement_advance,
    record_sign_refinement_chain,
    sample_identity_key,
)
from .roots import refine_root_once, refresh_sign_samples
